-- Initial schema v2; generated by tools/export-schema.py.
-- Existing v1 data is migrated by application initialization; do not drop legacy tables.

CREATE TABLE classes (
	class_id VARCHAR(128) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	parent_id VARCHAR(128), 
	is_active BOOLEAN NOT NULL, 
	is_provisional BOOLEAN NOT NULL, 
	introduced_taxonomy_version INTEGER NOT NULL, 
	deprecated_taxonomy_version INTEGER, 
	version INTEGER NOT NULL, 
	PRIMARY KEY (class_id)
);

CREATE TABLE config (
	config_key VARCHAR(32) NOT NULL, 
	taxonomy_version INTEGER NOT NULL, 
	policy_version INTEGER NOT NULL, 
	PRIMARY KEY (config_key)
);

CREATE TABLE cultivars (
	cultivar_id VARCHAR(64) NOT NULL, 
	name VARCHAR(128) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	version INTEGER NOT NULL, 
	PRIMARY KEY (cultivar_id)
);

CREATE TABLE meta_lock (
	id SERIAL NOT NULL, 
	rev INTEGER NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE meta_schema (
	name VARCHAR(32) NOT NULL, 
	value VARCHAR(64) NOT NULL, 
	PRIMARY KEY (name)
);

CREATE TABLE users (
	user_id VARCHAR(36) NOT NULL, 
	username VARCHAR(32) NOT NULL, 
	display_name VARCHAR(64) NOT NULL, 
	role VARCHAR(16) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	last_login_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (user_id), 
	UNIQUE (username)
);

CREATE TABLE exports (
	export_id VARCHAR(36) NOT NULL, 
	owner_id VARCHAR(36) NOT NULL, 
	format VARCHAR(16) NOT NULL, 
	filters JSON NOT NULL, 
	snapshot_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	taxonomy_version INTEGER NOT NULL, 
	item_count INTEGER NOT NULL, 
	status VARCHAR(16) NOT NULL, 
	zip_key VARCHAR(512), 
	zip_sha256 VARCHAR(64), 
	zip_size BIGINT, 
	error_code VARCHAR(32), 
	error_detail TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (export_id), 
	FOREIGN KEY(owner_id) REFERENCES users (user_id)
);

CREATE INDEX ix_exports_created ON exports (created_at);

CREATE INDEX ix_exports_status ON exports (status);

CREATE TABLE sessions (
	token_hash VARCHAR(64) NOT NULL, 
	kind VARCHAR(16) NOT NULL, 
	session_id VARCHAR(36) NOT NULL, 
	user_id VARCHAR(36) NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	revoked BOOLEAN NOT NULL, 
	PRIMARY KEY (token_hash), 
	FOREIGN KEY(user_id) REFERENCES users (user_id)
);

CREATE INDEX ix_sessions_family ON sessions (session_id);

CREATE INDEX ix_sessions_user ON sessions (user_id);

CREATE TABLE uploads (
	upload_id VARCHAR(36) NOT NULL, 
	sample_id VARCHAR(36) NOT NULL, 
	owner_id VARCHAR(36) NOT NULL, 
	state VARCHAR(16) NOT NULL, 
	declared_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	upload_completed_at TIMESTAMP WITH TIME ZONE, 
	content_hash VARCHAR(64) NOT NULL, 
	declaration JSON NOT NULL, 
	PRIMARY KEY (upload_id), 
	UNIQUE (sample_id), 
	FOREIGN KEY(owner_id) REFERENCES users (user_id)
);

CREATE TABLE idempotency (
	key_hash VARCHAR(64) NOT NULL, 
	request_hash VARCHAR(64) NOT NULL, 
	export_id VARCHAR(36) NOT NULL, 
	PRIMARY KEY (key_hash), 
	FOREIGN KEY(export_id) REFERENCES exports (export_id)
);

CREATE TABLE samples (
	sample_id VARCHAR(36) NOT NULL, 
	owner_id VARCHAR(36) NOT NULL, 
	upload_id VARCHAR(36) NOT NULL, 
	tree_id VARCHAR(64), 
	original_cultivar_id VARCHAR(64) NOT NULL, 
	original_cultivar_name VARCHAR(128) NOT NULL, 
	original_part VARCHAR(16) NOT NULL, 
	original_class_id VARCHAR(128) NOT NULL, 
	original_class_name VARCHAR(128) NOT NULL, 
	symptoms TEXT, 
	note TEXT, 
	taxonomy_version INTEGER NOT NULL, 
	upload_state VARCHAR(16) NOT NULL, 
	upload_completed_at TIMESTAMP WITH TIME ZONE, 
	excluded BOOLEAN NOT NULL, 
	review_status VARCHAR(16) NOT NULL, 
	final_cultivar_id VARCHAR(64), 
	final_cultivar_name VARCHAR(128), 
	final_part VARCHAR(16), 
	final_class_id VARCHAR(128), 
	final_class_name VARCHAR(128), 
	review_note TEXT, 
	review_version INTEGER NOT NULL, 
	reviewed_by_display_name VARCHAR(64), 
	reviewed_at TIMESTAMP WITH TIME ZONE, 
	review_events JSON NOT NULL, 
	PRIMARY KEY (sample_id), 
	FOREIGN KEY(owner_id) REFERENCES users (user_id), 
	UNIQUE (upload_id), 
	FOREIGN KEY(upload_id) REFERENCES uploads (upload_id)
);

CREATE INDEX ix_samples_completed ON samples (upload_completed_at);

CREATE INDEX ix_samples_review ON samples (upload_state, review_status, excluded);

CREATE TABLE images (
	image_id VARCHAR(36) NOT NULL, 
	sample_id VARCHAR(36) NOT NULL, 
	sort_index INTEGER NOT NULL, 
	view_type VARCHAR(16) NOT NULL, 
	captured_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	device_timezone VARCHAR(64) NOT NULL, 
	device_model VARCHAR(64), 
	mime_type VARCHAR(32) NOT NULL, 
	width INTEGER NOT NULL, 
	height INTEGER NOT NULL, 
	file_size BIGINT NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	receive_status VARCHAR(16) NOT NULL, 
	file_key VARCHAR(512), 
	quality_status VARCHAR(16) NOT NULL, 
	quality_reason_code VARCHAR(32), 
	quality_note TEXT, 
	quality_version INTEGER NOT NULL, 
	quality_reviewed_by_display_name VARCHAR(64), 
	quality_reviewed_at TIMESTAMP WITH TIME ZONE, 
	clock_skew_suspected BOOLEAN NOT NULL, 
	quality_events JSON NOT NULL, 
	PRIMARY KEY (image_id), 
	CONSTRAINT uq_image_order UNIQUE (sample_id, sort_index), 
	FOREIGN KEY(sample_id) REFERENCES samples (sample_id)
);

CREATE TABLE export_items (
	export_id VARCHAR(36) NOT NULL, 
	image_id VARCHAR(36) NOT NULL, 
	sample_id VARCHAR(36) NOT NULL, 
	sort_index INTEGER NOT NULL, 
	file_name VARCHAR(128) NOT NULL, 
	file_key VARCHAR(512), 
	class_id VARCHAR(128) NOT NULL, 
	class_name VARCHAR(128), 
	sha256 VARCHAR(64) NOT NULL, 
	PRIMARY KEY (export_id, image_id), 
	FOREIGN KEY(export_id) REFERENCES exports (export_id), 
	FOREIGN KEY(image_id) REFERENCES images (image_id), 
	FOREIGN KEY(sample_id) REFERENCES samples (sample_id)
);
